63: export function makeWasenderTransport(
64:   db?: BetterSqlite3.Database,
65:   storage: StorageProvider = createStorageFromEnv(),
66:   fetchImpl: typeof fetch = fetch,
67: ): (input: SendMessageInput & { apiKey: string }) => Promise<{ providerMessageId: string }> {
68:   return async (input) => {
69:     let payload: Record<string, unknown> = { to: input.toPhone };
70: 
71:     if (input.kind === "media" && input.mediaId && db) {
72:       const asset = db
73:         .prepare("SELECT filename, mime_type, r2_key FROM media_assets WHERE id = ?")
74:         .get(input.mediaId) as { filename: string; mime_type: string; r2_key: string } | undefined;
75: 
76:       if (asset) {
77:         const publicUrl = storage.getPublicUrl(asset.r2_key);
78:         const mime = asset.mime_type.toLowerCase();
79: 
80:         if (mime.startsWith("image/")) {
81:           payload.imageUrl = publicUrl;
82:           if (input.text) payload.text = input.text;
83:         } else if (mime.startsWith("audio/")) {
84:           payload.audioUrl = publicUrl;
85:         } else if (mime.startsWith("video/")) {
86:           payload.videoUrl = publicUrl;
87:           if (input.text) payload.text = input.text;
88:         } else {
89:           payload.documentUrl = publicUrl;
90:           payload.fileName = asset.filename;
91:           if (input.text) payload.text = input.text;
92:         }
93:       } else {
94:         if (input.text) payload.text = input.text;
95:       }
96:     } else {
97:       payload.text = input.text ?? "";
98:     }
99: 
100:     const res = await fetchImpl(WASENDER_API, {
101:       method: "POST",
102:       headers: {
103:         Authorization: `Bearer ${input.apiKey}`,
104:         "Content-Type": "application/json",
105:       },
106:       body: JSON.stringify(payload),
107:     });
108: 
109:     if (!res.ok) throw { status: res.status, body: await res.text().catch(() => "") };
110: 
111:     const body = (await res.json().catch(() => ({}))) as {
112:       data?: { key?: { id?: string }; message_id?: string; id?: string };
113:     };
114:     const providerMessageId =
115:       body.data?.key?.id ?? body.data?.message_id ?? body.data?.id ?? `unconfirmed-${Date.now()}`;
116:     return { providerMessageId };
117:   };
118: }
