29:   v1: { messaged: number; replied: number },
30:   v2: { messaged: number; replied: number }
31: ) {
32:   const n1 = v1.messaged;
33:   const n2 = v2.messaged;
34:   if (n1 < 5 || n2 < 5) return null;
35:   const p1 = v1.replied / n1;
36:   const p2 = v2.replied / n2;
37:   const pPool = (v1.replied + v2.replied) / (n1 + n2);
38:   const se = Math.sqrt(pPool * (1 - pPool) * (1 / n1 + 1 / n2));
39:   if (se === 0) return null;
40:   const z = (p1 - p2) / se;
41:   const absZ = Math.abs(z);
42:   const pValue = 2 * (1 - normalCdf(absZ));
43:   const confidence = Math.max(0, Math.min(100, Math.round((1 - pValue) * 1000) / 10));
44:   return {
45:     z,
