6: 
7: URL: https://www.wasenderapi.com/api-docs/getting-started/how-to-receive-messages-and-media-from-wasenderapi
8: Description: A developer's guide to receiving and processing real-time message events. This documentation details the flattened JSON payload, unified messageBody field, and handling for both Private and Group chats.
9: 
10: Details:
11: How to Handle Incoming WhatsApp Messages
12: 
13:  When you get a new WhatsApp message, we send a POST request to your server (webhook). Inside is a JSON payload with all the message details.
14: 
15:  The Message Payload
16: 
17:  The JSON structure has been updated. The data.messages field is now a single object (not an array) containing the normalized key, the unified messageBody, and the raw message content.
18: 
19:  {
20:  "event": "messages.received",
21:  "timestamp": 1633456789,
22:  "data": {
23:  "messages": {
24:  "key": {
25:  "id": "3EB0X123456789",
26:  "fromMe": false,
27:  "remoteJid": "123456789@lid",
28:  "cleanedSenderPn": "5551234567",
29:  "senderLid": "123456789@lid"
30:  },
31:  "messageBody": "Hello! This is a test.",
32:  "message": {
33:  "conversation": "Hello! This is a test."
34:  }
35:  }
36:  }
37: }
38: 
39:  Key Fields Explained:
40: 
41:  - key.cleanedSenderPn: (Recommended) The sender's phone number in private chats. Use this for your database or logic.
42: 
43:  - key.cleanedParticipantPn: (Recommended) The sender's phone number in group chats.
44: 
45:  - key.remoteJid: The unique ID of the chat.
46: 
47:  ⚠️ Important: Do not rely on remoteJid to be a phone number. It can often be a LID (Linked ID, ending in @lid). Always use the "cleaned" fields if you need the specific phone number.
48: 
49:  - messageBody: The unified text content of the message. Whether it's a text message, an image caption, or a reply, the text will always be here.
50: 
51:  Reading the Message Content
52: 
53:  1. The Easy Way (Text)
54: 
55:  You no longer need to check multiple fields (like conversation vs extendedTextMessage). Just use data.messages.messageBody.
56: 
57:  2. Media Messages
58: 
59:  For media, look inside the raw data.messages.message object for keys like imageMessage, videoMessage, or audioMessage.
60: 
61:  How to Decrypt Media Files
62: 
63:  Important Update: You no longer have to decrypt the media yourself if you don’t want to. We now provide a secure API endpoint that does it for you automatically: Decrypt Media File API.
64: 
65:  If you choose to decrypt manually, use the code examples below.
66: 
67: Code examples:
68: ```php
69: <?php
70: 
71: declare(strict_types=1);
72: 
73: // The directory to save downloaded media files.
74: // Make sure this directory exists and your web server can write to it.
75: define('DOWNLOAD_DIR', __DIR__ . '/downloads');
76: 
77: /**
78:  * A simple logging function for demonstration.
79:  * In a real application, you would use a proper logger like Monolog.
80:  */
81: function logMessage(string $message): void
82: {
83:     $timestamp = date('Y-m-d H:i:s');
84:     file_put_contents('webhook.log', "[$timestamp] $message\n", FILE_APPEND);
85: }
86: 
87: /**
88:  * Finds the first available media object and its type from the message.
89:  */
90: function findMediaInfo(array $messageObject): ?array
91: {
92:     $mediaKeys = [
93:         'imageMessage'    => 'image',
94:         'videoMessage'    => 'video',
95:         'audioMessage'    => 'audio',
96:         'documentMessage' => 'document',
97:         'stickerMessage'  => 'sticker',
98:     ];
99: 
100:     foreach ($mediaKeys as $key => $type) {
101:         if (isset($messageObject[$key])) {
102:             return [$messageObject[$key], $type];
103:         }
104:     }
105:     return null;
106: }
107: 
108: /**
109:  * Downloads a file from a URL.
110:  */
111: function downloadFile(string $url)
112: {
113:     $context = stream_context_create(['http' => ['follow_location' => true]]);
114:     return file_get_contents($url, false, $context);
115: }
116: 
117: /**
118:  * Derives the decryption keys using HKDF.
119:  */
120: function getDecryptionKeys(string $mediaKey, string $mediaType): string
121: {
122:     $info = match ($mediaType) {
123:         'image', 'sticker' => 'WhatsApp Image Keys',
124:         'video'           => 'WhatsApp Video Keys',
125:         'audio'           => 'WhatsApp Audio Keys',
126:         'document'        => 'WhatsApp Document Keys',
127:         default           => throw new Exception("Invalid media type: {$mediaType}"),
128:     };
129:     
130:     return hash_hkdf('sha256', base64_decode($mediaKey), 112, $info, '');
131: }
132: 
133: /**
134:  * Main function to decrypt and save a media file.
135:  */
136: function handleMediaDecryption(array $mediaInfo, string $mediaType, string $messageId): void
137: {
138:     $url = $mediaInfo['url'] ?? null;
139:     $mediaKey = $mediaInfo['mediaKey'] ?? null;
140:     
141:     if (!$url || !$mediaKey) {
142:         throw new Exception("Media object is missing url or mediaKey.");
143:     }
144: 
145:     $encryptedData = downloadFile($url);
146:     if (!$encryptedData) {
147:         throw new Exception("Failed to download media from URL: {$url}");
148:     }
149: 
150:     $keys = getDecryptionKeys($mediaKey, $mediaType);
151:     $iv = substr($keys, 0, 16);
152:     $cipherKey = substr($keys, 16, 32);
153:     $ciphertext = substr($encryptedData, 0, -10);
154: 
155:     $decryptedData = openssl_decrypt($ciphertext, 'aes-256-cbc', $cipherKey, OPENSSL_RAW_DATA, $iv);
156:     if ($decryptedData === false) {
157:         throw new Exception('Failed to decrypt media.');
158:     }
159: 
160:     if (!is_dir(DOWNLOAD_DIR)) {
161:         mkdir(DOWNLOAD_DIR, 0755, true);
162:     }
163:     $mimeType = $mediaInfo['mimetype'] ?? 'application/octet-stream';
164:     $extension = explode('/', $mimeType)[1] ?? 'bin';
165:     $filename = $mediaInfo['fileName'] ?? "{$messageId}.{$extension}";
166:     $outputPath = DOWNLOAD_DIR . '/' . basename($filename);
167:     
168:     file_put_contents($outputPath, $decryptedData);
169:     logMessage("Successfully decrypted and saved media to: {$outputPath}");
170: }
171: 
172: // --- MAIN WEBHOOK PROCESSING LOGIC ---
173: 
174: $jsonPayload = file_get_contents('php://input');
175: $payload = json_decode($jsonPayload, true);
176: 
177: // 1. Access data.messages (Direct Object Access)
178: $messageData = $payload['data']['messages'] ?? null;
179: 
180: if (!$messageData) {
181:     logMessage('Webhook received but no message data found.');
182:     http_response_code(200);
183:     exit();
184: }
185: 
186: $key = $messageData['key'] ?? [];
187: $messageId = $key['id'] ?? 'unknown_id';
188: 
189: // 2. Identify Sender (Group vs Private)
190: $sender = $key['cleanedParticipantPn'] ?? $key['cleanedSenderPn'] ?? $key['remoteJid'];
191: 
192: // 3. Get Unified Text Body
193: $messageContent = $messageData['messageBody'] ?? '';
194: 
195: logMessage("Processing message from {$sender}. ID: {$messageId}");
196: 
197: if (!empty($messageContent)) {
198:     logMessage("Text: {$messageContent}");
199:     // TODO: Save text message to your database here.
200: }
201: 
202: // 4. Handle Media
203: $mediaInfo = findMediaInfo($messageData['message'] ?? []);
204: if ($mediaInfo) {
205:     try {
206:         logMessage("Media found. Type: {$mediaInfo[1]}. Attempting to decrypt...");
207:         handleMediaDecryption($mediaInfo[0], $mediaInfo[1], $messageId);
208:     } catch (Exception $e) {
209:         logMessage("ERROR processing media: " . $e->getMessage());
210:     }
211: }
212: 
213: http_response_code(200);
214: logMessage("--- Finished processing webhook ---");
215: ```
