30: export function classifyError(err: unknown): ErrorClass {
31:   const e = err as { status?: number; code?: string } | null;
32:   if (typeof e?.status === "number") {
33:     if (e.status === 429 || e.status >= 500) return "retryable";
34:     if (e.status >= 400 && e.status < 500) return "non-retryable";
35:   }
