65: export interface Scheduler {
66:   /** Process all due jobs once. Safe to call concurrently; calls coalesce. */
67:   tick(): Promise<void>;
68:   /** Insert a job and wake the scheduler immediately. Returns the job id. */
69:   enqueue(input: EnqueueInput): number;
70: }
