72: /**
73:  * Single global worker over the unified `jobs` table (ADR 0001).
74:  * Workflow executions stay independent (PRD §22); only outbound sends are
75:  * serialized per session by the rate limiter (PRD §24–25).
76:  */
77: export function createScheduler(
78:   db: BetterSqlite3.Database,
79:   executeJob: JobExecutor,
80:   clock: Clock = realClock,
81: ): Scheduler {
82:   // ponytail: in-memory limiter resets on restart — worst case one early send
83:   // per session right after a restart; acceptable for a safety policy, not an SLA.
84:   const nextSendAt = new Map<number, number>();
85:   // Ticks are chained, never dropped: a wake arriving mid-tick runs as the
86:   // next pass instead of being lost to a boolean guard.
87:   let tail: Promise<void> = Promise.resolve();
88: 
89:   const iso = (ms: number) => new Date(ms).toISOString();
90: 
91:   const selectDue = db.prepare(`
92:     SELECT j.*, we.session_id
93:     FROM jobs j JOIN workflow_executions we ON we.id = j.execution_id
94:     WHERE j.status = 'pending' AND j.run_at <= ?
95:     ORDER BY j.run_at
96:     LIMIT 50
97:   `);
98:   const bumpAttempts = db.prepare("UPDATE jobs SET attempts = attempts + 1 WHERE id = ?");
99:   const markDone = db.prepare("UPDATE jobs SET status = 'done' WHERE id = ?");
100:   const deferTo = db.prepare("UPDATE jobs SET run_at = ? WHERE id = ?");
101:   const failJob = db.prepare("UPDATE jobs SET status = 'failed', last_error = ? WHERE id = ?");
102:   const failExecution = db.prepare(
103:     "UPDATE workflow_executions SET status = 'failed', finished_at = ? WHERE id = ?",
104:   );
105:   const backoffJob = db.prepare("UPDATE jobs SET run_at = ?, last_error = ? WHERE id = ?");
106:   const logEvent = db.prepare(
107:     "INSERT INTO events (event_type, execution_id, data) VALUES ('job.failed', ?, ?)",
108:   );
109: 
110:   async function dispatch(job: JobRow): Promise<void> {
111:     bumpAttempts.run(job.id);
112:     try {
113:       await executeJob(job);
114:       markDone.run(job.id);
115:     } catch (err) {
116:       const cls = classifyError(err);
117:       const attempts = job.attempts + 1;
118:       if (cls === "non-retryable" || attempts >= MAX_ATTEMPTS) {
119:         failJob.run(String(err), job.id);
120:         failExecution.run(iso(clock.now()), job.execution_id);
121:         logEvent.run(job.execution_id, JSON.stringify({ job_id: job.id, error: String(err), class: cls }));
122:       } else {
123:         // retryable and unknown both retry — unknown capped by MAX_ATTEMPTS
124:         const backoff = BASE_BACKOFF_MS * 2 ** (attempts - 1); // 30s, 60s
125:         backoffJob.run(iso(clock.now() + backoff), String(err), job.id);
126:       }
127:     }
128:   }
129: 
130:   async function runPass(): Promise<void> {
131:     const due = selectDue.all(iso(clock.now())) as JobRow[];
132:     for (const job of due) {
133:       if (job.type === "send_message") {
134:         // Reserve the session's next free slot; later same-session jobs in this
135:         // batch see the moved slot and defer behind it (keeps strict ≥5s spacing).
136:         const slot = Math.max(clock.now(), nextSendAt.get(job.session_id) ?? 0);
137:         if (clock.now() < slot) {
138:           deferTo.run(iso(slot), job.id);
139:           continue;
140:         }
141:         nextSendAt.set(job.session_id, slot + MIN_SEND_INTERVAL_MS);
142:       }
143:       await dispatch(job);
144:     }
145:   }
146: 
147:   function tick(): Promise<void> {
148:     const pass = tail.then(runPass, runPass);
149:     tail = pass.then(
150:       () => undefined,
151:       () => undefined,
152:     );
153:     return pass;
154:   }
155: 
156:   function enqueue(input: EnqueueInput): number {
157:     const info = db
158:       .prepare("INSERT INTO jobs (type, execution_id, node_key, payload, run_at) VALUES (?, ?, ?, ?, ?)")
159:       .run(
160:         input.type,
161:         input.executionId,
162:         input.nodeKey ?? null,
163:         JSON.stringify(input.payload ?? {}),
164:         iso(input.runAt?.getTime() ?? clock.now()),
165:       );
166:     void tick(); // due-now work starts immediately; the poller covers the rest
167:     return Number(info.lastInsertRowid);
168:   }
169: 
170:   return { tick, enqueue };
171: }
