        SUM(CASE WHEN status = 'waiting' THEN 1 ELSE 0 END) AS waiting,
        SUM(CASE WHEN status = 'waiting_input' THEN 1 ELSE 0 END) AS waitingInput,
        SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) AS completed,
