      FROM workflow_executions
    `).get() ?? {}) as Record<string, number | null>;

    return {
      total: row.total ?? 0,
      running: row.running ?? 0,
      waiting: row.waiting ?? 0,
      waitingInput: row.waitingInput ?? 0,
