        VALUES ('workflow.step', ?, ?, ?, ?)
      `).run(exec.session_id, exec.contact_id, job.execution_id, JSON.stringify({ node_key: job.node_key }));
      if (job.node_key) advanceFrom(job.execution_id, job.node_key);
      else step(job.execution_id);
      return;
    }

