      setWorkflows(wfList);
      const expMap: Record<number, string> = {};
      for (const e of expList) expMap[e.id] = e.name;
      setExperiments(expMap);
    } catch (e) {
      setError(String(e));
    }
  }

  useEffect(() => {
    void refresh();
  }, []);

