            onSubmit={async (e) => {
              e.preventDefault();
              await api.deleteWorkflow(String(deleting.id));
              setDeleting(null);
              void refresh();
            }}
          >
            <p className="modal-title">Delete “{deleting.name}”?</p>
            <p className="page-subtitle" style={{ margin: "0.25rem 0 1.25rem" }}>
