        const apiKey = row?.api_key_encrypted?.toString("utf8") || process.env.WASENDER_PAT;
        if (!apiKey) throw { status: 500, code: "NO_SESSION_KEY" };
        return makeWasenderTransport(db)({ ...input, apiKey });
      },
