args.ReplacementContent:
try {
  while (true) {
    if (!exec.current_node_key) return complete(executionId, null);
    const node = getNode.get(exec.workflow_id, exec.current_node_key) as
      | { type: string; config: string }
      | undefined;
    if (!node) return complete(executionId, exec.current_node_key);

    db.prepare(`
      INSERT INTO events (event_type, session_id, contact_id, execution_id, data)
      VALUES ('node.entered', ?, ?, ?, ?)
    `).run(exec.session_id, exec.contact_id, executionId, JSON.stringify({ node_key: exec.current_node_key, type: node.type }));

    switch (node.type) {
      case "send_text": {
        const config = JSON.parse(node.config || "{}") as { text?: string };
        const interpolated = interpolateVariables(config.text ?? "", vars, contact, session, triggerMsg, rng);
        enqueueSend(executionId, exec.current_node_key, {
          kind: "text",
          text: interpolated,
        });
        setWaiting(executionId, exec.current_node_key);
        return;
      }
      case "send_media": {
        const config = JSON.parse(node.config || "{}") as { text?: string; caption?: string; mediaId?: number };
        const rawCaption = config.caption ?? config.text;
        const caption = rawCaption ? interpolateVariables(rawCaption, vars, contact, session, triggerMsg, rng) : undefined;
        enqueueSend(executionId, exec.current_node_key, {
          kind: "media",
          text: caption,
          mediaId: config.mediaId,
        });
        setWaiting(executionId, exec.current_node_key);
        return;
      }
      case "send_menu": {
        const config = JSON.parse(node.config || "{}") as MenuNodeConfig;
        const fallbackPolicy = config.fallback ?? DEFAULT_FALLBACK_POLICY;
        vars.reprompt_count = 0;
        updateExecutionVars.run(JSON.stringify(vars), executionId);

        const menuText = buildMenuText(config, vars, contact, session, triggerMsg, rng);
        enqueueSend(executionId, exec.current_node_key, {
          kind: "text",
          text: menuText,
        });
        setWaitingInput(executionId, exec.current_node_key);
        return;
      }
      case "collect_input": {
        setWaitingInput(executionId, exec.current_node_key);
        return;
      }
      case "delay": {
        const config = JSON.parse(node.config || "{}") as { duration_ms?: number };
        const duration = config.duration_ms ?? 0;
        scheduler.enqueue({
          type: "resume",
          executionId,
          nodeKey: exec.current_node_key,
          runAt: new Date(clock.now() + duration),
        });
        setWaiting(executionId, exec.current_node_key);
        return;
      }
      case "random_delay": {
        const config = JSON.parse(node.config || "{}") as { min_ms?: number; max_ms?: number };
        const min = config.min_ms ?? 0;
        const max = config.max_ms ?? min;
        const duration = min + Math.floor(rng() * (max - min));
        scheduler.enqueue({
          type: "resume",
          executionId,
          nodeKey: exec.current_node_key,
          runAt: new Date(clock.now() + duration),
        });
        setWaiting(executionId, exec.current_node_key);
        return;
      }
      case "condition": {
        const config = JSON.parse(node.config || "{}") as ConditionNodeConfig;
        const isMatch = evaluateCondition(config, vars, contact);
        db.prepare(`
          INSERT INTO events (event_type, session_id, contact_id, execution_id, data)
          VALUES ('condition.evaluated', ?, ?, ?, ?)
        `).run(exec.session_id, exec.contact_id, executionId, JSON.stringify({ node_key: exec.current_node_key, result: isMatch }));

        const handle = isMatch ? "true" : "false";
        const edge = getEdgeByHandle.get(exec.workflow_id, exec.current_node_key, handle) as
          | { target_key: string }
          | undefined;

        if (edge) {
          exec.current_node_key = edge.target_key;
          break;
        }
        const defEdge = getNextKey.get(exec.workflow_id, exec.current_node_key) as { target_key: string } | undefined;
        if (defEdge) {
          exec.current_node_key = defEdge.target_key;
          break;
        }
        return complete(executionId, exec.current_node_key);
      }
      case "keyword": {
        const config = JSON.parse(node.config || "{}") as {
          phrase?: string;
          phrases?: string[];
          algorithm?: MatchingAlgorithm;
          threshold?: number;
        };
        const algorithm = config.algorithm ?? "exact";
        const threshold = config.threshold ?? 0.8;
        const phrases = config.phrases && config.phrases.length > 0 ? config.phrases : config.phrase ? [config.phrase] : [];

        let matched = false;
        let highestScore = 0;
        for (const p of phrases) {
          const res = evaluateMatch({ phrase: p, algorithm, threshold }, triggerMsg?.text ?? "");
          if (res.matched) {
            matched = true;
            highestScore = Math.max(highestScore, res.score);
          }
        }

        if (!matched) return complete(executionId, exec.current_node_key);

        const handle = "on_match";
        const matchEdge = getEdgeByHandle.get(exec.workflow_id, exec.current_node_key, handle) as
          | { target_key: string }
          | undefined;

        if (matchEdge) {
          exec.current_node_key = matchEdge.target_key;
          db.prepare(
            "INSERT INTO events (event_type, session_id, contact_id, execution_id, message_id, data) VALUES ('trigger.matched', ?, ?, ?, ?, ?)",
          ).run(
            exec.session_id,
            exec.contact_id,
            executionId,
            triggerMsg?.id ?? null,
            JSON.stringify({ algorithm, score: highestScore }),
          );
          break;
        } else {
          const defEdge = getNextKey.get(exec.workflow_id, exec.current_node_key) as { target_key: string } | undefined;
          if (defEdge) {
            exec.current_node_key = defEdge.target_key;
            break;
          }
          return complete(executionId, exec.current_node_key);
        }
      }
      case "split_test": {
        const config = JSON.parse(node.config || "{}") as SplitTestNodeConfig;
        const variants = config.variants ?? [];
        if (variants.length === 0) {
          const next = getNextKey.get(exec.workflow_id, exec.current_node_key) as { target_key: string } | undefined;
          if (!next) return complete(executionId, exec.current_node_key);
          exec.current_node_key = next.target_key;
          break;
        }

        const totalWeight = variants.reduce((sum, v) => sum + (v.weight || 1), 0);
        let random = rng() * totalWeight;
        let selected = variants[0];
        for (const v of variants) {
