const [saveStatus, setSaveStatus] = useState<"saved" | "saving" | "unsaved">("saved");
const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null);
const isInitialMount = useRef(true);

// Debounced auto-save & localStorage draft shield
useEffect(() => {
  if (isInitialMount.current) {
    isInitialMount.current = false;
    return;
  }

  setSaveStatus("unsaved");
  try {
    const draftGraph = fromFlow({ nodes, edges }, meta);
    localStorage.setItem(`wastat_draft_${id}`, JSON.stringify(draftGraph));
  } catch {}

  if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);
  saveTimeoutRef.current = setTimeout(async () => {
    setSaveStatus("saving");
    try {
      await api.saveWorkflow(id, fromFlow({ nodes, edges }, meta));
      setSaveStatus("saved");
    } catch {
      setSaveStatus("unsaved");
    }
  }, 1500);

  return () => {
    if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);
  };
}, [nodes, edges, meta, id]);

async function save() {
  setSaveStatus("saving");
  try {
    await api.saveWorkflow(id, fromFlow({ nodes, edges }, meta));
    setSaveStatus("saved");
    showToast("Workflow saved successfully");
  } catch {
    setSaveStatus("unsaved");
    showToast("Save failed — check your connection and retry", true);
  }
}

async function duplicate() {
  try {
    const res = await api.duplicateWorkflow(id);
    showToast("Workflow duplicated");
    window.location.hash = `#/workflows/${res.id}`;
  } catch {
    showToast("Duplicate failed", true);
  }
}

const selectedNode = nodes.find((n) => n.id === selectedKey)?.data.graphNode as GraphNode | undefined;
const selectedEdge = edges.find((e) => e.id === selectedEdgeId);

return (
  <div className="editor">
    <header className="editor-toolbar">
      <button className="btn btn-ghost" onClick={onBack} aria-label="Back to workflows">
        ← All
      </button>
      <input
        className="editor-name"
        value={meta.name}
        onChange={(e) => setMeta({ ...meta, name: e.target.value })}
        aria-label="Workflow name"
        placeholder="Untitled workflow"
      />

      <div className="toolbar-experiment-select">
        <label htmlFor="wf-session-select" style={{ fontSize: "0.75rem", color: "var(--muted)" }}>
          📱 Number:
        </label>
        <select
          id="wf-session-select"
          className="input-select-sm"
          value={meta.sessionId ?? ""}
          onChange={(e) => {
            const val = e.target.value;
            setMeta({ ...meta, sessionId: val ? Number(val) : null });
          }}
        >
          <option value="">All Numbers (Global)</option>
          {sessions.map((s) => (
            <option key={s.id} value={s.id}>
              {s.name} ({s.providerSessionId})
            </option>
          ))}
        </select>
      </div>

      <div className="toolbar-experiment-select">
        <label htmlFor="wf-exp-select" style={{ fontSize: "0.75rem", color: "var(--muted)" }}>
          🧪 Exp:
        </label>
        <select
          id="wf-exp-select"
          className="input-select-sm"
          value={meta.experimentId ?? ""}
          onChange={(e) => {
            const val = e.target.value;
            setMeta({ ...meta, experimentId: val ? Number(val) : null });
          }}
        >
          <option value="">None (Standalone)</option>
          {experiments.map((exp) => (
            <option key={exp.id} value={exp.id}>
              {exp.name}
            </option>
          ))}
        </select>
      </div>

      <button className="btn btn-ghost btn-sm" onClick={autoLayout} title="Auto-layout graph">
        ⚡ Layout
      </button>

      <button
        className="btn btn-ghost btn-sm"
        onClick={() => setShowSimulator(true)}
        style={{ borderColor: "var(--accent)", color: "var(--accent)" }}
      >
        ▶ Simulator
      </button>

      <a
        href={`#/executions?workflowId=${id}`}
        className="btn btn-ghost btn-sm"
        style={{ textDecoration: "none", display: "inline-flex", alignItems: "center" }}
        title="Inspect live execution traces"
      >
        ⚡ Traces
      </a>

      {/* Auto-Save Status Badge */}
      <span
        style={{
          fontSize: "0.75rem",
          fontWeight: 600,
          padding: "2px 8px",
          borderRadius: "4px",
          background: saveStatus === "saving" ? "rgba(245, 158, 11, 0.15)" : saveStatus === "saved" ? "rgba(16, 185, 129, 0.15)" : "rgba(239, 68, 68, 0.15)",
          color: saveStatus === "saving" ? "#f59e0b" : saveStatus === "saved" ? "#10b981" : "#ef4444",
          border: `1px solid ${saveStatus === "saving" ? "rgba(245, 158, 11, 0.3)" : saveStatus === "saved" ? "rgba(16, 185, 129, 0.3)" : "rgba(239, 68, 68, 0.3)"}`,
        }}
      >
        {saveStatus === "saving" ? "⏳ Auto-saving..." : saveStatus === "saved" ? "✓ Saved" : "● Unsaved"}
      </span>

      <label className="switch">
        <input
          type="checkbox"
          checked={meta.active === 1}
          onChange={(e) => setMeta({ ...meta, active: e.target.checked ? 1 : 0 })}
          aria-label="Live — replies to matching incoming messages"
        />
        <span className="switch-track" aria-hidden />
        <span className="switch-label">{meta.active === 1 ? "Live" : "Draft"}</span>
      </label>
      <button className="btn btn-ghost btn-sm" onClick={duplicate} title="Duplicate this workflow">
        Duplicate
      </button>
      <button className="btn btn-primary" onClick={save}>
        Save
      </button>
    </header>

