import { makeWasenderAdmin } from "./wasender-admin.js";
import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";

function loadEnv() {
  const envPaths = [join(process.cwd(), ".env"), join(process.cwd(), "..", "..", ".env")];
  for (const p of envPaths) {
    if (existsSync(p)) {
      const content = readFileSync(p, "utf8");
      for (const line of content.split("\n")) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith("#")) continue;
        const eqIdx = trimmed.indexOf("=");
        if (eqIdx !== -1) {
          const key = trimmed.slice(0, eqIdx).trim();
          const val = trimmed.slice(eqIdx + 1).trim().replace(/^["']|["']$/g, "");
          if (!process.env[key]) process.env[key] = val;
        }
      }
    }
  }
}

async function testWasenderMedia() {
  loadEnv();
  const pat = process.env.WASENDER_PAT;
  if (!pat) {
    console.error("WASENDER_PAT is missing");
    return;
  }
  const admin = makeWasenderAdmin(pat);
  const safari = await admin.getSession(105947);
  const patrickPhone = "+237676637853";
  const wasenderBaseUrl = process.env.WASENDER_BASE_URL ?? "https://www.wasenderapi.com/api";

  console.log(`[Diagnostic] Testing Wasender Media API Calls from Safari (105947) to ${patrickPhone}...`);

  // Test 1: Image call
  const imgPayload = {
    to: patrickPhone,
    imageUrl: "https://images.unsplash.com/photo-1580587771525-78b9dba3b914?w=1200",
    text: "📸 Test Image from Safari",
  };
  console.log(`\n--- Test 1: POST /send-message (Image) ---`);
  console.log(`Payload:`, JSON.stringify(imgPayload, null, 2));

  const imgRes = await fetch(`${wasenderBaseUrl}/send-message`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${safari.api_key}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(imgPayload),
  });
  console.log(`HTTP Status:`, imgRes.status);
  console.log(`Response Body:`, await imgRes.text());

  // Test 2: Video call
  const vidPayload = {
    to: patrickPhone,
    videoUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4",
    text: "🎥 Test Video from Safari",
  };
  console.log(`\n--- Test 2: POST /send-message (Video) ---`);
  console.log(`Payload:`, JSON.stringify(vidPayload, null, 2));

  const vidRes = await fetch(`${wasenderBaseUrl}/send-message`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${safari.api_key}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(vidPayload),
  });
  console.log(`HTTP Status:`, vidRes.status);
  console.log(`Response Body:`, await vidRes.text());
}

testWasenderMedia().catch(console.error);

